window.cityPicker = new autoComplete({
  name: 'City suggestions',
  selector: '#city',
  data: { src: ['Aveiro', 'Braga', 'Coimbra', 'Faro', 'Lisbon', 'Porto', 'Portimão'] },
  resultsList: { id: 'city-list' },
  events: { input: { selection: event => { window.cityPicker.input.value = event.detail.selection.value; } } }
});
// Dismiss suggestions with Escape while preserving typed input
window.cityPicker.input.addEventListener('keydown', event => {
  if (event.key === 'Escape') {
    event.preventDefault();
    if (typeof window.cityPicker.close === 'function') {
      window.cityPicker.close();
    }
  }
});
